// 나머지 분야: 원본 펜 그림을 조각별로 하나씩 나타나게 함(용어 글씨는 잘라냄)
function rasterMotion(term){
 const id=Number(term.id),m=motionRaster[id];if(!m)return null;
 const [si,x,y,w,h,parts]=m,[file,W,H]=motionSheets[si],n=parts.length;
 const img=`<image href="/pictograms/${file}" x="0" y="0" width="${W}" height="${H}" style="mix-blend-mode:multiply"/>`;
 let defs='',body='';
 parts.forEach(([px,py,pw,ph,sp],i)=>{
  const slot=n>1?Math.round(1+i*9/(n-1)):1,cid=`mr${id}-${i}`;
  defs+=`<clipPath id="${cid}"><rect x="${px}" y="${py}" width="${pw}" height="${ph}"/></clipPath>`;
  body+=`<g class="p${slot}" style="transform-box:view-box;transform-origin:${px+pw/2}px ${py+ph/2}px"><g class="${sp?'blink':''}" clip-path="url(#${cid})">${img}</g></g>`;
 });
 const frame=el('div','term-pictogram mp');
 frame.innerHTML=`<svg class="mp-wipe" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${term.term} 움직이는 픽토그램" preserveAspectRatio="xMidYMid meet"><defs>${defs}</defs><g class="m-all">${body}</g></svg>`;
 return frame;
}
function motionPictogram(term){
 const id=Number(term.id),body=motionPictograms[id];
 if(!body)return rasterMotion(term);
 const frame=el('div','term-pictogram mp');
 frame.innerHTML=`<svg viewBox="0 0 400 250" role="img" aria-label="${term.term} 움직이는 픽토그램" preserveAspectRatio="xMidYMid meet"><g class="m-all" fill="none" stroke="#1b1b1b" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
 return frame;
}
